select  from club_direct_merchant_receivable
where id = #{id} and topic_id = #{topicId} and payer_club_id = #{payerClubId}
  and merchant_member_id = #{merchantMemberId} for update

select  from club_direct_merchant_receivable

    and topic_id = #{topicId}
    and payer_club_id = #{payerClubId}
    and merchant_member_id = #{merchantMemberId}
    and 1 = 0

order by id desc

mapper.update:
update club_direct_merchant_receivable
set status = 'SETTLED', settled_at = now(), settled_by = #{actor}, pay_voucher_no = #{voucher}
where  and status = 'OPEN' and per_head_fee_snapshot > 0

update club_direct_merchant_receivable
set status = 'REFUNDED', refunded_at = now(), refunded_by = #{actor}, refund_voucher_no = #{voucher}
where  and status = 'REFUND_DUE'
